import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const dir = fileURLToPath(new URL('../src/webui/app/', import.meta.url))
const outFile = fileURLToPath(new URL('../src/webui/app/sources.ts', import.meta.url))
const cssFile = fileURLToPath(new URL('../src/webui/styles.css', import.meta.url))
const stylesFile = fileURLToPath(new URL('../src/webui/styles.ts', import.meta.url))

// Working-tree line endings depend on core.autocrlf, so normalise before embedding;
// otherwise the generated files differ between platforms and the browser receives
// different bytes than the ones committed.
const read = (file) => fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n')

let out = `// This file is generated by scripts/generate-webui-sources.mjs — do not edit by hand.
// It embeds the browser-side ES modules so the Node server can serve them
// without shipping raw .js assets on disk.

export const sources: Record<string, string> = {
`

const names = fs.readdirSync(dir).filter((name) => name.endsWith('.js')).sort()
for (const name of names) {
    const key = name.slice(0, -3)
    out += `    ${JSON.stringify(key)}: ${JSON.stringify(read(path.join(dir, name)))},\n`
}

out = out.replace(/,\n$/, '\n') + `}\n`
fs.writeFileSync(outFile, out)

const css = read(cssFile)
if (css.includes('`') || css.includes('${')) {
    throw new Error(
        'src/webui/styles.css must not contain a backtick or ${ so it can be emitted as a String.raw template'
    )
}
// Emitted as String.raw rather than JSON.stringify to keep the stylesheet diffable
// line by line instead of as one escaped string.
fs.writeFileSync(
    stylesFile,
    `// This file is generated by scripts/generate-webui-sources.mjs — do not edit by hand.
// Edit src/webui/styles.css instead.

export const styles = String.raw\`
${css}\`
`
)

console.log(
    `generated src/webui/app/sources.ts (${names.length} modules) and src/webui/styles.ts`
)
